# v111: „Milyen messze volt Róma? Utazási idő és szállítási költség” kártya (hu/en). Adat: orbis/calc.py -> orbis/data.json
import json
D=json.load(open('orbis/data.json'));S={s['id']:s for s in D['sites']}
# (id, magyar név, angol név, szárazföld belseje=1, címke a diagramon=1)
C=[('50286','Ostia és Portus','Ostia and Portus',0,0),('50322','Puteoli (Pozzuoli)','Puteoli (Pozzuoli)',0,0),('50323','Ravenna','Ravenna',0,0),('50251','Mediolanum (Milánó)','Mediolanum (Milan)',1,1),('50034','Aquileia','Aquileia',0,0),('50086','Brundisium (Brindisi)','Brundisium (Brindisi)',0,0),('50455','Syracusae (Siracusa)','Syracusae (Syracuse)',0,0),
 ('50107','Karthágó','Carthage',0,1),('50230','Lepcis Magna','Lepcis Magna',0,0),('50250','Massilia (Marseille)','Massilia (Marseille)',0,0),('50429','Lugdunum (Lyon)','Lugdunum (Lyon)',1,0),('50379','Tarraco (Tarragona)','Tarraco (Tarragona)',0,0),('50179','Gades (Cádiz)','Gades (Cádiz)',0,1),
 ('50235','Londinium (London)','Londinium (London)',0,1),('50124','Augusta Treverorum (Trier)','Augusta Treverorum (Trier)',1,1),('50105','Carnuntum','Carnuntum',1,1),('50035','Aquincum (Budapest)','Aquincum (Budapest)',1,1),('50343','Savaria (Szombathely)','Savaria (Szombathely)',1,1),('50359','Sirmium (Sremska Mitrovica)','Sirmium (Sremska Mitrovica)',1,1),
 ('50389','Thessalonica','Thessalonica',0,0),('50050','Athén','Athens',0,0),('50549','Korinthosz','Corinth',0,0),('50129','Constantinopolis (Byzantium)','Constantinople (Byzantium)',0,1),('50169','Ephesus','Ephesus',0,0),('50024','Antiochia','Antioch',0,1),('50094','Caesarea Maritima','Caesarea Maritima',0,0),('50017','Alexandria','Alexandria',0,1),('50138','Küréné','Cyrene',0,0),('50290','Palmüra','Palmyra',1,1)]
def build(l):
    H=l=='hu';T=lambda h,e:h if H else e
    fmt=(lambda n:f'{n:,}'.replace(',',' ')) if H else (lambda n:f'{n:,}')
    def d(x,k=1):
        s=f'{x:.{k}f}';return s.replace('.',',') if H else s
    o=[]
    o.append('    <section class="card" id="orbiscard">')
    o.append('      <h2>'+T('Milyen messze volt Róma? Utazási idő és szállítási költség','How far was Rome? Travel time and transport cost')+'</h2>')
    o.append('      <p class="hint">'+T('A Stanford Egyetem ORBIS modellje a római világ úthálózatát, hajózható folyóit és tengeri útvonalait egyetlen hálózatba köti, és kiszámolja, mennyi idő és mennyi pénz volt eljutni egyik helyről a másikra. A Kr. u. 200 körüli állapotot közelíti 632 hellyel, mintegy 85 000 km úttal, 28 000 km folyóval és 1026 tengeri útvonallal. A kártya azt mutatja, mit ad a modell, ha a cél Róma.','The ORBIS model of Stanford University joins the road network, navigable rivers and sea routes of the Roman world into a single network and calculates how much time and money it took to get from one place to another. It approximates conditions around AD 200 with 632 sites, some 85,000 km of roads, 28,000 km of rivers and 1,026 sea routes. The card shows what the model gives when the destination is Rome.')+'</p>')
    # pontdiagram: légvonal km – dénár/kg
    Wd,Ht,L,R,Tp,Bt=860,360,50,16,14,44;pw=Wd-L-R;ph=Ht-Tp-Bt;XM,YM=2500,13
    xx=lambda v:L+v/XM*pw;yy=lambda v:Tp+ph-v/YM*ph
    s=['      <svg class="orbsvg" viewBox="0 0 %d %d" role="img" aria-label="%s">'%(Wd,Ht,T('Szállítási költség Rómáig a légvonalbeli távolság függvényében','Transport cost to Rome against straight-line distance'))]
    for v in (0,2,4,6,8,10,12): s.append('<line class="gr" x1="%d" x2="%d" y1="%.1f" y2="%.1f"/><text class="ax" x="%d" y="%.1f" text-anchor="end">%d</text>'%(L,Wd-R,yy(v),yy(v),L-6,yy(v)+5,v))
    for v in (0,500,1000,1500,2000,2500): s.append('<line class="tk" x1="%.1f" x2="%.1f" y1="%d" y2="%d"/><text class="ax" x="%.1f" y="%d" text-anchor="%s">%s</text>'%(xx(v),xx(v),Tp+ph,Tp+ph+5,xx(v),Tp+ph+22,'end' if v==XM else 'middle',fmt(v)+' km'))
    for i,hu,en,inl,lab in C:
        p=S[i];s.append('<circle class="%s" cx="%.1f" cy="%.1f" r="6"><title>%s: %s km, %s</title></circle>'%('pin' if inl else 'pse',xx(p['km']),yy(p['cj']),T(hu,en),fmt(p['km']),d(p['cj'])))
        if lab: s.append('<text class="lb" x="%.1f" y="%.1f" text-anchor="%s">%s</text>'%(xx(p['km'])+(-9 if p['km']>2200 else 9),yy(p['cj'])+(-9 if i=='50024' else 5),'end' if p['km']>2200 else 'start',T(hu,en).split(' (')[0]))
    s.append('</svg>');o.append(''.join(s))
    o.append('      <p class="hint aqleg"><span class="sw opse"></span> '+T('tengeren vagy a tenger közelében elérhető város · ','city reachable by sea or near the sea · ')+'<span class="sw opin"></span> '+T('a szárazföld belsejében fekvő város. Vízszintesen a légvonalbeli távolság Rómától, függőlegesen egy kilogramm búza Rómába szállításának költsége dénárban (júliusi indulás, a legolcsóbb útvonal).','inland city. Horizontally the straight-line distance from Rome, vertically the cost in denarii of carrying one kilogram of wheat to Rome (departure in July, cheapest route).')+'</p>')
    SRC=T('W. Scheidel – E. Meeks, <i>ORBIS: The Stanford Geospatial Network Model of the Roman World</i>, orbis.stanford.edu; a modell lekérdezése Róma középponttal, 2026. november 12-én. A légvonalbeli távolság saját számítás.','W. Scheidel – E. Meeks, <i>ORBIS: The Stanford Geospatial Network Model of the Roman World</i>, orbis.stanford.edu; the model queried with Rome as centre on 12 November 2026. Straight-line distance is our own calculation.')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+SRC+'</p>')
    al,sv,ca,si=S['50017'],S['50343'],S['50107'],S['50359']
    o.append('      <p class="hint">'+T('<b>A távolságot a pénz és az idő mérte, nem a kilométer.</b> Alexandria légvonalban %s km-re van, a búza kilóját mégis %s dénárért lehetett onnan Rómába hozni; a %s km-re fekvő Savariából ugyanez %s dénárba került, vagyis harmadakkora távolságról több mint ötször annyiba. Karthágóból (%s km) %s nap alatt lehetett Rómába érni, a hasonló távolságra fekvő Sirmiumból (%s km) %s nap alatt. Ez az egyik oka, hogy Róma Egyiptom és Africa gabonájából élt, és nem a Duna-vidékéből.'%(fmt(al['km']),d(al['cj']),fmt(sv['km']),d(sv['cj']),fmt(ca['km']),d(ca['tj']),fmt(si['km']),d(si['tj'])),'<b>Distance was measured in money and time, not in kilometres.</b> Alexandria is %s km away in a straight line, yet a kilo of wheat could be brought from there to Rome for %s denarii; from Savaria, %s km away, the same cost %s denarii, that is, more than five times as much from a third of the distance. From Carthage (%s km) Rome could be reached in %s days, from Sirmium at a similar distance (%s km) in %s days. This is one reason why Rome lived on the grain of Egypt and Africa and not on that of the Danube lands.'%(fmt(al['km']),d(al['cj']),fmt(sv['km']),d(sv['cj']),fmt(ca['km']),d(ca['tj']),fmt(si['km']),d(si['tj'])))+'</p>')
    o.append('      <div class="regwrap"><table class="regtab orbtab">')
    o.append('        <thead><tr><th>'+T('Város','City')+'</th><th>'+T('Légvonalban (km)','Straight line (km)')+'</th><th>'+T('Rómába (nap)','To Rome (days)')+'</th><th>'+T('Rómából (nap)','From Rome (days)')+'</th><th>'+T('Búza Rómába (dénár/kg)','Wheat to Rome (den./kg)')+'</th></tr></thead>')
    o.append('        <tbody>')
    for i,hu,en,inl,lab in sorted(C,key=lambda c:S[c[0]]['km']):
        p=S[i];o.append('          <tr><td>'+T(hu,en)+'</td><td>'+fmt(p['km'])+'</td><td>'+d(p['tj'])+'</td><td>'+d(p['fj'])+'</td><td>'+d(p['cj'],2)+'</td></tr>')
    o.append('        </tbody>')
    o.append('      </table></div>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+SRC+'</p>')
    o.append('      <p class="hint">'+T('Az idő a leggyorsabb útvonalé júliusi indulással, szárazföldön gyalog (napi 30 km), tengeren vitorlással. A költség a legolcsóbb útvonalé: a szárazföldi szakaszokon szamárral, a folyókon polgári hajóval, a tengeren gyorsabb vitorlással. Az oda- és visszaút ideje a szelek miatt tér el: Rómából Alexandriába %s, vissza %s nap.'%(d(al['fj']),d(al['tj'])),'Time is that of the fastest route with departure in July, on foot by land (30 km a day), under sail at sea. Cost is that of the cheapest route: by donkey on the land stretches, by civilian boat on rivers, by a faster sailing ship at sea. The outward and return journeys differ because of the winds: from Rome to Alexandria %s days, back %s days.'%(d(al['fj']),d(al['tj'])))+'</p>')
    o.append('      <p class="hint">'+T('<b>Mire kell vigyázni.</b> Ezek egy modell eredményei, nem feljegyzett utazások: átlagos szél- és hullámviszonyokat feltételeznek, egyedi viharral vagy kikötői várakozással nem számolnak, és a valóságban télen a hajózás nagyrészt szünetelt. A dénárban adott költség a modell saját árrendszerében értendő, ezért itt az arányok számítanak, nem az összegek. Az árrendeletben szereplő hajófuvardíjakat lásd az „Árak és bérek 301-ben” kártyán, a gabonaellátást a „Róma élelmezése” kártyán.','<b>What to watch for.</b> These are the results of a model, not recorded journeys: they assume average wind and wave conditions, take no account of individual storms or waiting in port, and in reality sailing largely stopped in winter. The cost in denarii is to be understood within the model’s own price system, so it is the ratios that matter here, not the sums. For the sea freight rates of the Price Edict see the “Prices and wages in 301” card, for the grain supply the “Feeding Rome” card.')+'</p>')
    o.append('    </section>')
    return '\n'.join(o)+'\n'
SUB=('utazási idő és a búza szállítási költsége 29 városból Rómába az ORBIS modell szerint','travel time and the cost of carrying wheat to Rome from 29 cities according to the ORBIS model')
SRCLI=lambda l:('      <li><b>Utazási idő és szállítási költség.</b> W. Scheidel – E. Meeks: <i>ORBIS: The Stanford Geospatial Network Model of the Roman World</i>, Stanford University (<a href="https://orbis.stanford.edu/">orbis.stanford.edu</a>); a modell leírása: W. Scheidel: Orbis: the Stanford geospatial network model of the Roman world, Princeton/Stanford Working Papers in Classics, 2015. A modell hat lekérdezése Róma középponttal (2026. november 12.); a modellhez kifejezett adatlicenc nem tartozik, ezért csak 29 kiválasztott város eredménye szerepel, a forrás megnevezésével.</li>' if l=='hu' else '      <li><b>Travel time and transport cost.</b> W. Scheidel – E. Meeks: <i>ORBIS: The Stanford Geospatial Network Model of the Roman World</i>, Stanford University (<a href="https://orbis.stanford.edu/">orbis.stanford.edu</a>); description of the model: W. Scheidel: Orbis: the Stanford geospatial network model of the Roman world, Princeton/Stanford Working Papers in Classics, 2015. Six queries of the model with Rome as centre (12 November 2026); the model carries no explicit data licence, so only the results for 29 selected cities are shown, with attribution.</li>')
if __name__=='__main__':
    print(len(C),len(build('hu').split('\n')),len(build('en').split('\n')))
    al,sv=S['50017'],S['50343'];print(sv['cj']/al['cj'],sv['km']/al['km'])
